using UnityEngine;using UDK7M;
namespace GameActions
{
 public sealed class SurfaceLightning:MonoBehaviour
 {
  public UDK7MBoss boss;public Transform[] surfaceAnchors;public Material coreMaterial,glowMaterial;public int boltCount=7,segments=20;public float spread=5,roughness=.3f;LineRenderer[] cores,glows;Light[] lights;float seed;
  void Start(){seed=Random.value*100;cores=new LineRenderer[boltCount];glows=new LineRenderer[boltCount];for(int i=0;i<boltCount;i++){cores[i]=Line("Arc core "+i,coreMaterial,.035f);glows[i]=Line("Arc glow "+i,glowMaterial,.16f);}lights=new Light[2];for(int i=0;i<2;i++){var go=new GameObject("Arc point light "+i);go.transform.SetParent(transform,false);lights[i]=go.AddComponent<Light>();lights[i].type=LightType.Point;lights[i].color=i==0?new Color(.2f,.65f,1):new Color(.65f,.15f,1);lights[i].range=4;lights[i].intensity=2;lights[i].shadows=LightShadows.None;}}
  LineRenderer Line(string name,Material material,float width){var go=new GameObject(name);go.transform.SetParent(transform,false);var l=go.AddComponent<LineRenderer>();l.sharedMaterial=material;l.useWorldSpace=true;l.positionCount=segments;l.widthMultiplier=width;l.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;l.receiveShadows=false;l.startColor=l.endColor=Color.white;return l;}
  void LateUpdate(){if(cores==null)return;if(surfaceAnchors==null||surfaceAnchors.Length==0){var group=transform.parent.Find("VFX Surface Sockets");if(group)surfaceAnchors=group.GetComponentsInChildren<Transform>();}for(int i=0;i<boltCount;i++){Vector3 end=surfaceAnchors!=null&&surfaceAnchors.Length>1?surfaceAnchors[1+i%(surfaceAnchors.Length-1)].position:transform.position+Vector3.up*(2+i%3);float a=i*Mathf.PI*2/boltCount+Time.time*.15f;Vector3 start=transform.position+new Vector3(Mathf.Sin(a)*spread,3,Mathf.Cos(a)*spread);foreach(var hit in Physics.RaycastAll(start+Vector3.up*4,Vector3.down,12,~0,QueryTriggerInteraction.Ignore))if((!boss||!hit.transform.IsChildOf(boss.transform))&&hit.normal.y>.5f){start=hit.point+Vector3.up*.04f;break;}for(int j=0;j<segments;j++){float t=j/(float)(segments-1),envelope=Mathf.Sin(t*Mathf.PI);float frame=Mathf.Floor(Time.time*24);var jitter=new Vector3(Mathf.PerlinNoise(seed+i*13+j*1.7f,frame)*2-1,Mathf.PerlinNoise(j*7+seed,frame+i)*2-1,Mathf.PerlinNoise(i*31+j,frame+seed)*2-1)*roughness*envelope;var p=Vector3.Lerp(start,end,t)+jitter;cores[i].SetPosition(j,p);glows[i].SetPosition(j,p);}if(i<2&&lights!=null)lights[i].transform.position=Vector3.Lerp(start,end,.7f);}}
 }
}
